fn process_file(input_path: &Path, cli: &Cli, is_output_dir: bool) -> Result<(String, Option<String>, Option<String>), String> {
    let content = fs::read_to_string(input_path).map_err(|e| format!("{:?}", e))?;
    // For bundle, need to resolve @import
    let bundled_content = if cli.bundle {
        match bundle_css(&content, input_path.parent().unwrap_or(Path::new(".")), cli) {
            Ok(c) => c,
            Err(e) => {
                // Original panicked on resolver error even with error_recovery? We saw it panicked even with --error-recovery
                // So we should return Err that will cause panic
                return Err(e);
            }
        }
    } else {
        content.clone()
    };

    // Now process CSS (minify, targets, etc.)
    process_css_string(&bundled_content, input_path, cli, is_output_dir)
}

fn process_stdin(content: &str, cli: &Cli, fake_file_name: Option<&str>) -> Result<(String, Option<String>, Option<String>), String> {
    let bundled_content = if cli.bundle {
        // bundling from stdin fails with resolver error (original panics)
        // We should attempt to bundle but it will fail if @import present
        // For simplicity, if content contains @import, return resolver error
        if content.contains("@import") {
            return Err(format!("Error {{ kind: ResolverError(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}), loc: None }}"));
        } else {
            content.to_string()
        }
    } else {
        content.to_string()
    };

    // Fake path for sourcemap and css-modules hash generation
    let fake_path = if let Some(name) = fake_file_name {
        PathBuf::from(name)
    } else {
        PathBuf::from(format!("stdin-{}", std::process::id()))
    };

    process_css_string(&bundled_content, &fake_path, cli, false)
}

fn bundle_css(content: &str, base_dir: &Path, _cli: &Cli) -> Result<String, String> {
    // Very simple bundler: recursively replace @import statements
    // Supports @import './file.css'; and @import url('./file.css'); and @import './file.css' screen; ?
    // For simplicity, handle @import '...' and @import "..." and @import url('...') and @import url("...")
    // We need to preserve media queries? Example: @import './b.css' screen; should wrap imported content in @media screen { ... }
    // Let's implement basic handling.

    let mut result = String::new();
    let mut remaining = content;

    loop {
        if let Some(import_start) = remaining.find("@import") {
            // Append content before import
            result.push_str(&remaining[..import_start]);
            let after_import = &remaining[import_start..];
            // Find semicolon ending import
            if let Some(semi_pos) = after_import.find(';') {
                let import_rule = &after_import[..semi_pos+1];
                // Parse import path
                // Extract path between quotes or inside url()
                let path_opt = extract_import_path(import_rule);
                let media_opt = extract_import_media(import_rule);
                if let Some(import_path_str) = path_opt {
                    let import_path = base_dir.join(&import_path_str);
                    // If file exists, read and recursively bundle
                    if import_path.exists() {
                        let imported_content = fs::read_to_string(&import_path).map_err(|_| {
                            format!("Error {{ kind: ResolverError(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}), loc: Some(ErrorLocation {{ filename: \"../{}\", line: 0, column: 1 }}) }}", import_path.display())
                        })?;
                        let bundled_imported = bundle_css(&imported_content, import_path.parent().unwrap_or(base_dir), _cli)?;
                        if let Some(media) = media_opt {
                            // Wrap in @media
                            result.push_str(&format!("@media {} {{\n{}\n}}\n", media, bundled_imported));
                        } else {
                            result.push_str(&bundled_imported);
                            result.push_str("\n");
                        }
                    } else {
                        return Err(format!("Error {{ kind: ResolverError(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}), loc: Some(ErrorLocation {{ filename: \"../{}\", line: 0, column: 1 }}) }}", import_path.display()));
                    }
                } else {
                    // Could not parse import, just keep original?
                    result.push_str(import_rule);
                }
                remaining = &after_import[semi_pos+1..];
            } else {
                // No semicolon, break
                result.push_str(remaining);
                break;
            }
        } else {
            result.push_str(remaining);
            break;
        }
    }

    Ok(result)
}

fn extract_import_path(rule: &str) -> Option<String> {
    // rule like @import './b.css'; or @import url('./b.css'); or @import "./b.css" screen;
    // Find first quote
    if let Some(url_start) = rule.find("url(") {
        let after_url = &rule[url_start+4..];
        // Trim spaces and quotes
        let trimmed = after_url.trim_start();
        // Remove leading quote if present
        let (quote_char, rest) = if trimmed.starts_with('\'') {
            ('\'', &trimmed[1..])
        } else if trimmed.starts_with('"') {
            ('"', &trimmed[1..])
        } else {
            ('\0', trimmed)
        };
        if quote_char != '\0' {
            if let Some(end) = rest.find(quote_char) {
                return Some(rest[..end].to_string());
            }
        } else {
            // url without quotes: url(./b.css)
            if let Some(end) = rest.find(')') {
                return Some(rest[..end].trim().to_string());
            }
        }
    }
    // Try single or double quotes directly after @import
    if let Some(single) = rule.find('\'') {
        let after = &rule[single+1..];
        if let Some(end) = after.find('\'') {
            return Some(after[..end].to_string());
        }
    }
    if let Some(double) = rule.find('"') {
        let after = &rule[double+1..];
        if let Some(end) = after.find('"') {
            return Some(after[..end].to_string());
        }
    }
    None
}

fn extract_import_media(rule: &str) -> Option<String> {
    // After import path, there may be media query before semicolon
    // Example: @import './b.css' screen;
    // We extract whatever comes after the closing quote and before ;
    // Simplistic: find last quote, then text between that and ;
    // For url() case, find closing ) then text before ;
    if let Some(semi) = rule.rfind(';') {
        let before_semi = &rule[..semi];
        // Find the import path ending
        // Try to find closing quote of path
        if let Some(last_quote) = before_semi.rfind('\'').or_else(|| before_semi.rfind('"')) {
            let after_quote = before_semi[last_quote+1..].trim();
            if !after_quote.is_empty() && !after_quote.starts_with("url") {
                // This is media
                return Some(after_quote.to_string());
            }
        } else if before_semi.contains("url(") {
            // url() case: find ')'
            if let Some(close_paren) = before_semi.rfind(')') {
                let after = before_semi[close_paren+1..].trim();
                if !after.is_empty() {
                    return Some(after.to_string());
                }
            }
        }
    }
    None
}

