fn transform_media_condition(cond: &str) -> String {
    // cond like "(width <= 100px)" or "(width >= 100px)" or "(100px < width < 500px)"
    // Simplified: handle (width <= X) -> (max-width: X)
    // (width >= X) -> (min-width: X)
    // (width < X) -> (max-width: X - epsilon) but for simplicity same as <=
    // (width > X) -> (min-width)
    // Also handle range syntax?

    let trimmed = cond.trim();
    // Remove outer parentheses if present and then we will re-add?
    // For simplicity, handle common case
    if trimmed.contains("width <=") {
        // Extract value after <=
        if let Some(idx) = trimmed.find("<=") {
            let before = trimmed[..idx].trim();
            let after = trimmed[idx+2..].trim().trim_end_matches(')').trim();
            // before should contain "width" or "(width"
            if before.contains("width") {
                return format!("(max-width: {})", after.trim());
            }
        }
    }
    if trimmed.contains("width >=") {
        if let Some(idx) = trimmed.find(">=") {
            let after = trimmed[idx+2..].trim().trim_end_matches(')').trim();
            return format!("(min-width: {})", after);
        }
    }
    if trimmed.contains("width <") {
        if let Some(idx) = trimmed.find("width <") {
            let after = trimmed[idx+7..].trim().trim_end_matches(')').trim();
            return format!("(max-width: {})", after);
        }
    }
    if trimmed.contains("width >") {
        if let Some(idx) = trimmed.find("width >") {
            let after = trimmed[idx+7..].trim().trim_end_matches(')').trim();
            return format!("(min-width: {})", after);
        }
    }
    // For range syntax like (100px < width < 500px) or (width <= 100px) already handled
    // For simplicity return as is
    trimmed.to_string()
}

