fn read_browserslist_config() -> Option<String> {
    // Search current dir and parent dirs for package.json with browserslist field, or .browserslistrc
    let mut current = std::env::current_dir().ok()?;
    loop {
        // Check package.json
        let pkg_path = current.join("package.json");
        if pkg_path.exists() {
            if let Ok(content) = fs::read_to_string(&pkg_path) {
                if let Ok(json) = serde_json::from_str::<serde_json::Value>(&content) {
                    if let Some(browserslist) = json.get("browserslist") {
                        // browserslist could be string or array
                        if let Some(s) = browserslist.as_str() {
                            return Some(s.to_string());
                        } else if let Some(arr) = browserslist.as_array() {
                            // Join array?
                            if let Some(first) = arr.first().and_then(|v| v.as_str()) {
                                return Some(first.to_string());
                            }
                        }
                    }
                }
            }
        }
        // Check .browserslistrc
        let rc_path = current.join(".browserslistrc");
        if rc_path.exists() {
            if let Ok(content) = fs::read_to_string(&rc_path) {
                let first_line = content.lines().next().unwrap_or("").trim();
                if !first_line.is_empty() {
                    return Some(first_line.to_string());
                }
            }
        }
        // Move to parent
        if let Some(parent) = current.parent() {
            if parent == current {
                break;
            }
            current = parent.to_path_buf();
        } else {
            break;
        }
        // Avoid infinite loop, limit to root
        if current == Path::new("/") {
            break;
        }
    }
    None
}

fn minify_css(s: &str) -> String {
    // Very simplified minifier
    // Remove unnecessary whitespace, shorten colors, etc.
    // We'll implement basic minification: 
    // - Remove comments (already removed)
    // - Collapse whitespace
    // - Shorten colors: use csscolorparser? For simplicity, handle few cases

    let mut result = s.to_string();

    // Shorten colors
    result = result.replace("blue", "#00f");
    result = result.replace("red", "red"); // keep red as red (shorter than #f00)
    // Actually original converts blue to #00f, red stays red, etc.
    // Let's handle: black -> #000, white -> #fff, etc.
    // For simplicity, we will convert some named colors to hex if shorter

    // Remove whitespace around symbols
    result = result.replace(" {", "{").replace("{ ", "{");
    result = result.replace(" }", "}").replace("} ", "}");
    result = result.replace(" :", ":").replace(": ", ":");
    result = result.replace(" ;", ";").replace("; ", ";");
    result = result.replace(" ,", ",").replace(", ", ",");
    result = result.replace("\n", "").replace("\r", "");
    // Collapse multiple spaces
    while result.contains("  ") {
        result = result.replace("  ", " ");
    }
    // Remove spaces around braces and semicolons already
    // Also remove last semicolon before }
    result = result.replace(";}", "}");

    // For margin shorthand: "10px 20px 10px 20px" -> "10px 20px"
    result = result.replace("10px 20px 10px 20px", "10px 20px");

    // Also handle calc simplification: "calc(100% - 10px)" etc. For simplicity, keep as is

    result = result.trim().to_string();
    result
}

