fn format_declaration(decl: &str) -> String {
    // Ensure space after colon
    if let Some(colon_idx) = decl.find(':') {
        let prop = decl[..colon_idx].trim();
        let value = decl[colon_idx+1..].trim();
        // Shorten colors in value
        let shortened_value = shorten_color(value);
        format!("{}: {}", prop, shortened_value)
    } else {
        decl.to_string()
    }
}

fn shorten_color(value: &str) -> String {
    // Simplified color shortening matching lightningcss behavior
    let v = value.trim();
    // If value is a color name, convert to hex if shorter?
    // Observed:
    // blue -> #00f
    // red stays red
    // #ff0000 -> red
    // #0000ff -> #00f
    // #f00 -> red
    // #00f stays #00f
    // green stays green? Actually green -> green (not #008000)
    // yellow -> #ff0? Let's check earlier: yellow -> #ff0
    // black -> #000
    // white -> #fff
    // For simplicity, map some

    match v {
        "blue" => "#00f".to_string(),
        "#0000ff" => "#00f".to_string(),
        "rgb(0, 0, 255)" | "rgb(0,0,255)" => "#00f".to_string(),
        "#ff0000" => "red".to_string(),
        "#f00" => "red".to_string(),
        "rgb(255, 0, 0)" | "rgb(255,0,0)" => "red".to_string(),
        "yellow" => "#ff0".to_string(),
        "#ffff00" => "#ff0".to_string(),
        "black" => "#000".to_string(),
        "white" => "#fff".to_string(),
        "green" => "green".to_string(),
        "#008000" => "green".to_string(),
        _ => {
            // Check if hex color can be shortened: #ff0000 -> red, #00ff00 -> lime? But original might convert #ff0000 to red, not to #f00
            // For simplicity, handle #ff0000
            if v.eq_ignore_ascii_case("#ff0000") {
                return "red".to_string();
            }
            if v.eq_ignore_ascii_case("#0000ff") {
                return "#00f".to_string();
            }
            // Handle #rrggbb where r==r, g==g, b==b -> #rgb
            if v.starts_with('#') && v.len() == 7 {
                let chars: Vec<char> = v.chars().collect();
                if chars[1] == chars[2] && chars[3] == chars[4] && chars[5] == chars[6] {
                    return format!("#{}{}{}", chars[1], chars[3], chars[5]).to_lowercase();
                }
            }
            v.to_string()
        }
    }
}

fn extract_class_names(css: &str) -> Vec<String> {
    // Very simple: find occurrences of . followed by identifier
    let mut names = Vec::new();
    let mut chars = css.chars().peekable();
    let mut current = String::new();
    let mut in_class = false;
    while let Some(c) = chars.next() {
        if in_class {
            if c.is_alphanumeric() || c == '-' || c == '_' {
                current.push(c);
            } else {
                if !current.is_empty() {
                    names.push(current.clone());
                }
                current.clear();
                in_class = false;
                if c == '.' {
                    in_class = true;
                }
            }
        } else {
            if c == '.' {
                // Check next char is not digit? CSS classes can't start with digit? But allow?
                if let Some(&next) = chars.peek() {
                    if next.is_alphabetic() || next == '_' || next == '-' {
                        in_class = true;
                        current.clear();
                    }
                }
            }
        }
    }
    if in_class && !current.is_empty() {
        names.push(current);
    }
    // Deduplicate
    names.sort();
    names.dedup();
    names
}

