    const CHARSET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    let mut result = String::new();
    let mut i = 0;
    while i < bytes.len() {
        let b0 = bytes[i] as u32;
        let b1 = if i+1 < bytes.len() { bytes[i+1] as u32 } else { 0 };
        let b2 = if i+2 < bytes.len() { bytes[i+2] as u32 } else { 0 };
        let triple = (b0 << 16) | (b1 << 8) | b2;
        let c0 = ((triple >> 18) & 0x3F) as usize;
        let c1 = ((triple >> 12) & 0x3F) as usize;
        let c2 = ((triple >> 6) & 0x3F) as usize;
        let c3 = (triple & 0x3F) as usize;
        result.push(CHARSET[c0] as char);
        result.push(CHARSET[c1] as char);
        if i+1 < bytes.len() {
            result.push(CHARSET[c2] as char);
        }
        if i+2 < bytes.len() {
            result.push(CHARSET[c3] as char);
        }
        i += 3;
    }
    result
}
