        --sourcemap
            Enable sourcemap, at <output_file>.map

    -t, --targets <TARGETS>


    -V, --version
            Print version information
"#;

#[derive(Debug, Default)]
struct Cli {
    input_files: Vec<PathBuf>,
    browserslist: bool,
    bundle: bool,
    css_modules: Option<Option<String>>,
    css_modules_dashed_idents: bool,
    css_modules_pattern: Option<String>,
    custom_media: bool,
    output_dir: Option<PathBuf>,
    error_recovery: bool,
    minify: bool,
    output_file: Option<PathBuf>,
    sourcemap: bool,
    targets: Option<String>,
    flag_order: Vec<String>,
}

fn print_help_and_exit() -> ! {
    print!("{}", HELP_TEXT);
    std::process::exit(0);
}
fn print_version_and_exit() -> ! {
    println!("lightningcss 1.0.0-alpha.70");
    std::process::exit(0);
}
fn error_unknown_arg(arg: &str) -> ! {
    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", arg);
    eprintln!("");
    eprintln!("\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`", arg, arg);
    eprintln!("");
    eprintln!("USAGE:");
    eprintln!("    executable [OPTIONS] [INPUT_FILE]...");
    eprintln!("");
    eprintln!("For more information try --help");
    std::process::exit(2);
}
fn error_missing_value(arg: &str, value_name: &str) -> ! {
    eprintln!("error: The argument '{} <{}>' requires a value but none was supplied", arg, value_name);
    eprintln!("");
    eprintln!("For more information try --help");
    std::process::exit(2);
}
fn error_required_output_sourcemap(cli: &Cli) -> ! {
    eprintln!("error: The following required arguments were not provided:");
    eprintln!("    <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>");
    eprintln!("");
    let mut usage_parts: Vec<String> = vec!["executable".to_string()];
    for flag in &cli.flag_order {
        if flag == "--css-modules" || flag.starts_with("--css-modules=") { continue; }
        if flag == "--sourcemap" { usage_parts.push("--sourcemap".to_string()); }
        else if flag == "--minify" || flag == "-m" { usage_parts.push("--minify".to_string()); }
        else if flag == "--bundle" { usage_parts.push("--bundle".to_string()); }
        else if flag == "--browserslist" { usage_parts.push("--browserslist".to_string()); }
        else if flag == "--custom-media" { usage_parts.push("--custom-media".to_string()); }
        else if flag == "--error-recovery" { usage_parts.push("--error-recovery".to_string()); }
        else if flag.starts_with("--css-modules-pattern") { usage_parts.push("--css-modules-pattern".to_string()); }
        else if flag.starts_with("--css-modules-dashed-idents") { usage_parts.push("--css-modules-dashed-idents".to_string()); }
        else if flag.starts_with("--targets") || flag.starts_with("-t") { usage_parts.push("--targets".to_string()); }
    }
    usage_parts.push("<--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>".to_string());
    if cli.css_modules.is_some() {
        usage_parts.push("<--css-modules [<CSS_MODULES>]>".to_string());
    }
    if !cli.input_files.is_empty() {
        usage_parts.push("<INPUT_FILE>...".to_string());
    }
    eprintln!("USAGE:");
    eprintln!("    {}", usage_parts.join(" "));
    eprintln!("");
    eprintln!("For more information try --help");
    std::process::exit(2);
}
fn error_conflict(a: &str, b: &str, usage: &str) -> ! {
    eprintln!("error: The argument '{}' cannot be used with '{}'", a, b);
    eprintln!("");
    eprintln!("USAGE:");
    eprintln!("    {}", usage);
    eprintln!("");
    eprintln!("For more information try --help");
    std::process::exit(2);
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut cli = Cli::default();
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => print_help_and_exit(),
            "-V" | "--version" => print_version_and_exit(),
            "--browserslist" => { cli.browserslist=true; cli.flag_order.push("--browserslist".to_string()); i+=1; }
            "--bundle" => { cli.bundle=true; cli.flag_order.push("--bundle".to_string()); i+=1; }
            "--css-modules" => {
                cli.flag_order.push("--css-modules".to_string());
                if i+1 < args.len() && !args[i+1].starts_with('-') {
                    let val=args[i+1].clone(); cli.css_modules=Some(Some(val)); i+=2;
                } else { cli.css_modules=Some(None); i+=1; }
            }
            s if s.starts_with("--css-modules=") => {
                cli.flag_order.push("--css-modules".to_string());
                let val=s["--css-modules=".len()..].to_string();
                if val.is_empty() { cli.css_modules=Some(None); } else { cli.css_modules=Some(Some(val)); }
                i+=1;
            }
            "--css-modules-dashed-idents" => { cli.css_modules_dashed_idents=true; cli.flag_order.push("--css-modules-dashed-idents".to_string()); i+=1; }
            "--css-modules-pattern" => {
                if i+1>=args.len() { error_missing_value("--css-modules-pattern","CSS_MODULES_PATTERN"); }
                let val=args[i+1].clone(); cli.css_modules_pattern=Some(val); cli.flag_order.push("--css-modules-pattern".to_string()); i+=2;
            }
            s if s.starts_with("--css-modules-pattern=") => {
                let val=s["--css-modules-pattern=".len()..].to_string(); cli.css_modules_pattern=Some(val); cli.flag_order.push("--css-modules-pattern".to_string()); i+=1;
            }
            "--custom-media" => { cli.custom_media=true; cli.flag_order.push("--custom-media".to_string()); i+=1; }
            "-d" | "--output-dir" => {
                let val=if arg.contains('='){ arg.splitn(2,'=').nth(1).unwrap().to_string() } else { if i+1>=args.len(){ error_missing_value("--output-dir","OUTPUT_DIR"); } let v=args[i+1].clone(); i+=1; v };
                cli.output_dir=Some(PathBuf::from(val)); cli.flag_order.push("--output-dir".to_string()); i+=1;
            }
            s if s.starts_with("--output-dir=") => { let val=s["--output-dir=".len()..].to_string(); cli.output_dir=Some(PathBuf::from(val)); cli.flag_order.push("--output-dir".to_string()); i+=1; }
            "--error-recovery" => { cli.error_recovery=true; cli.flag_order.push("--error-recovery".to_string()); i+=1; }
            "-m" | "--minify" => { cli.minify=true; cli.flag_order.push("--minify".to_string()); i+=1; }
            "-o" | "--output-file" => {
                let val=if arg.contains('='){ arg.splitn(2,'=').nth(1).unwrap().to_string() } else { if i+1>=args.len(){ error_missing_value("--output-file","OUTPUT_FILE"); } let v=args[i+1].clone(); i+=1; v };
                cli.output_file=Some(PathBuf::from(val)); cli.flag_order.push("--output-file".to_string()); i+=1;
            }
            s if s.starts_with("--output-file=") => { let val=s["--output-file=".len()..].to_string(); cli.output_file=Some(PathBuf::from(val)); cli.flag_order.push("--output-file".to_string()); i+=1; }
            "--sourcemap" => { cli.sourcemap=true; cli.flag_order.push("--sourcemap".to_string()); i+=1; }
            "-t" | "--targets" => {
                let val=if arg.contains('='){ arg.splitn(2,'=').nth(1).unwrap().to_string() } else { if i+1>=args.len(){ error_missing_value("--targets","TARGETS"); } let v=args[i+1].clone(); i+=1; v };
                cli.targets=Some(val); cli.flag_order.push("--targets".to_string()); i+=1;
            }
            s if s.starts_with("--targets=") => { let val=s["--targets=".len()..].to_string(); cli.targets=Some(val); cli.flag_order.push("--targets".to_string()); i+=1; }
            "--" => { i+=1; while i<args.len(){ cli.input_files.push(PathBuf::from(&args[i])); i+=1; } break; }
            s if s.starts_with('-') => error_unknown_arg(s),
            _ => { cli.input_files.push(PathBuf::from(arg)); i+=1; }
        }
    }
    if cli.browserslist && cli.targets.is_some() {
        error_conflict("--browserslist","--targets <TARGETS>","executable <--targets <TARGETS>|--browserslist> <INPUT_FILE>...");
    }
    if cli.output_file.is_some() && cli.output_dir.is_some() {
        error_conflict("--output-file <OUTPUT_FILE>","--output-dir <OUTPUT_DIR>","executable <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>> <INPUT_FILE>...");
    }
    if cli.sourcemap && cli.output_file.is_none() && cli.output_dir.is_none() {
        error_required_output_sourcemap(&cli);
    }
    if let Some(ref pat)=cli.css_modules_pattern {
        if let Err(e)=validate_pattern(pat){ eprintln!("{}",e); std::process::exit(1); }
    }
    if cli.input_files.len()>1 && cli.output_file.is_some(){
        eprintln!("Cannot use the --output-file option with multiple inputs. Use --output-dir instead.");
        std::process::exit(1);
    }
    if let Err(e)=run(cli){ eprintln!("{}",e); std::process::exit(1); }
}

fn validate_pattern(pattern: &str) -> Result<(), String> {
    let chars: Vec<char>=pattern.chars().collect();
    let mut i=0;
    while i<chars.len(){
        if chars[i]=='['{
            if let Some(end)=chars[i..].iter().position(|&c| c==']'){
                let end_idx=i+end;
                let placeholder=&pattern[i..=end_idx];
                if placeholder!="[hash]" && placeholder!="[local]" && placeholder!="[name]"{
                    return Err(format!("Error parsing CSS modules pattern: unknown placeholder \"{}\" at index {}",placeholder,i));
                }
                i=end_idx+1; continue;
            } else {
                return Err(format!("Error parsing CSS modules pattern: unclosed brackets at index {}",i));
            }
        }
        i+=1;
    }
    Ok(())
}

fn run(cli: Cli) -> Result<(), String> {
    for input_path in &cli.input_files {
        if !input_path.exists(){
            return Err(format!("Error: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}"));
        }
    }
    if !cli.input_files.is_empty(){
        if let Some(ref out_dir)=cli.output_dir{
            fs::create_dir_all(out_dir).ok();
            let explicit_json_path = match &cli.css_modules {
                Some(Some(s)) => Some(PathBuf::from(s)),
