            "-m" | "--minify" => { cli.minify=true; cli.flag_order.push("--minify".to_string()); i+=1; }
            "-o" | "--output-file" => {
                let val=if arg.contains('='){ arg.splitn(2,'=').nth(1).unwrap().to_string() } else { if i+1>=args.len(){ error_missing_value("--output-file","OUTPUT_FILE"); } let v=args[i+1].clone(); i+=1; v };
                cli.output_file=Some(PathBuf::from(val)); cli.flag_order.push("--output-file".to_string()); i+=1;
            }
            s if s.starts_with("--output-file=") => { let val=s["--output-file=".len()..].to_string(); cli.output_file=Some(PathBuf::from(val)); cli.flag_order.push("--output-file".to_string()); i+=1; }
            "--sourcemap" => { cli.sourcemap=true; cli.flag_order.push("--sourcemap".to_string()); i+=1; }
            "-t" | "--targets" => {
                let val=if arg.contains('='){ arg.splitn(2,'=').nth(1).unwrap().to_string() } else { if i+1>=args.len(){ error_missing_value("--targets","TARGETS"); } let v=args[i+1].clone(); i+=1; v };
                cli.targets=Some(val); cli.flag_order.push("--targets".to_string()); i+=1;
            }
            s if s.starts_with("--targets=") => { let val=s["--targets=".len()..].to_string(); cli.targets=Some(val); cli.flag_order.push("--targets".to_string()); i+=1; }
            "--" => { i+=1; while i<args.len(){ cli.input_files.push(PathBuf::from(&args[i])); i+=1; } break; }
            s if s.starts_with('-') => error_unknown_arg(s),
            _ => { cli.input_files.push(PathBuf::from(arg)); i+=1; }
        }
    }
    if cli.browserslist && cli.targets.is_some() {
        error_conflict("--browserslist","--targets <TARGETS>","executable <--targets <TARGETS>|--browserslist> <INPUT_FILE>...");
    }
    if cli.output_file.is_some() && cli.output_dir.is_some() {
        error_conflict("--output-file <OUTPUT_FILE>","--output-dir <OUTPUT_DIR>","executable <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>> <INPUT_FILE>...");
    }
    if cli.sourcemap && cli.output_file.is_none() && cli.output_dir.is_none() {
        error_required_output_sourcemap(&cli);
    }
    if let Some(ref pat)=cli.css_modules_pattern {
        if let Err(e)=validate_pattern(pat){ eprintln!("{}",e); std::process::exit(1); }
    }
    if cli.input_files.len()>1 && cli.output_file.is_some(){
        eprintln!("Cannot use the --output-file option with multiple inputs. Use --output-dir instead.");
        std::process::exit(1);
    }
    if let Err(e)=run(cli){ eprintln!("{}",e); std::process::exit(1); }
}

fn validate_pattern(pattern: &str) -> Result<(), String> {
    let chars: Vec<char>=pattern.chars().collect();
    let mut i=0;
    while i<chars.len(){
        if chars[i]=='['{
            if let Some(end)=chars[i..].iter().position(|&c| c==']'){
                let end_idx=i+end;
                let placeholder=&pattern[i..=end_idx];
                if placeholder!="[hash]" && placeholder!="[local]" && placeholder!="[name]"{
                    return Err(format!("Error parsing CSS modules pattern: unknown placeholder \"{}\" at index {}",placeholder,i));
                }
                i=end_idx+1; continue;
            } else {
                return Err(format!("Error parsing CSS modules pattern: unclosed brackets at index {}",i));
            }
        }
        i+=1;
    }
    Ok(())
}

fn run(cli: Cli) -> Result<(), String> {
    for input_path in &cli.input_files {
        if !input_path.exists(){
            return Err(format!("Error: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}"));
        }
    }
    if !cli.input_files.is_empty(){
        if let Some(ref out_dir)=cli.output_dir{
            fs::create_dir_all(out_dir).ok();
            let explicit_json_path = match &cli.css_modules {
                Some(Some(s)) => Some(PathBuf::from(s)),
                _=>None,
            };
            let is_css_modules=cli.css_modules.is_some();
            for input_path in &cli.input_files{
                let (css_output,json_output,map_output)=match process_file(input_path,&cli,true){
                    Ok(v)=>v,
                    Err(e)=>{
                        if cli.error_recovery{ return Err(e); } else { panic_with_original_format(&e,input_path); }
                    }
                };
                let file_name=input_path.file_name().unwrap_or_else(|| std::ffi::OsStr::new("output.css"));
                let out_css_path=out_dir.join(file_name);
                if let Some(parent)=out_css_path.parent(){ fs::create_dir_all(parent).ok(); }
                fs::write(&out_css_path,css_output.as_bytes()).map_err(|e|{
                    if e.kind()==io::ErrorKind::NotFound{ format!("Error: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}") } else { format!("Error: {}",e) }
                })?;
                if is_css_modules{
                    if let Some(ref explicit_path)=explicit_json_path{
                        if let Some(parent)=explicit_path.parent(){ if !parent.as_os_str().is_empty() && !parent.exists(){ return Err(format!("Error: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}")); } }
                        if let Some(ref json_str)=json_output{
                            fs::write(explicit_path,json_str.as_bytes()).map_err(|e|{
                                if e.kind()==io::ErrorKind::NotFound{ format!("Error: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}") } else { format!("Error: {}",e) }
                            })?;
                        }
                    } else {
                        let out_json_path=out_css_path.with_extension("json");
                        if let Some(ref json_str)=json_output{ fs::write(&out_json_path,json_str.as_bytes()).ok(); }
                    }
                }
                if cli.sourcemap{
                    if let Some(ref map_str)=map_output{
                        let map_path=PathBuf::from(format!("{}.map",out_css_path.display()));
                        fs::write(&map_path,map_str.as_bytes()).ok();
                    }
                }
            }
        } else if let Some(ref out_file)=cli.output_file{
            let input_path=&cli.input_files[0];
            if let Some(parent)=out_file.parent(){ if !parent.as_os_str().is_empty(){ fs::create_dir_all(parent).ok(); } }
            let (css_output,json_output,map_output)=match process_file(input_path,&cli,false){
                Ok(v)=>v,
                Err(e)=>{ if cli.error_recovery{ return Err(e); } else { panic_with_original_format(&e,input_path); } }
            };
            fs::write(out_file,css_output.as_bytes()).map_err(|e|{
                if e.kind()==io::ErrorKind::NotFound{ format!("Error: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}") } else { format!("Error: {}",e) }
            })?;
            if cli.css_modules.is_some(){
                if let Some(Some(ref explicit))=cli.css_modules{
                    let explicit_path=PathBuf::from(explicit);
                    if let Some(parent)=explicit_path.parent(){ if !parent.as_os_str().is_empty() && !parent.exists(){ return Err(format!("Error: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}")); } }
                    if let Some(ref json_str)=json_output{
                        fs::write(&explicit_path,json_str.as_bytes()).map_err(|e|{
                            if e.kind()==io::ErrorKind::NotFound{ format!("Error: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}") } else { format!("Error: {}",e) }
                        })?;
                    }
                } else if let Some(None)=cli.css_modules{
                    let out_json_path=out_file.with_extension("json");
                    if let Some(ref json_str)=json_output{ fs::write(&out_json_path,json_str.as_bytes()).ok(); }
                }
            }
            if cli.sourcemap{
                if let Some(ref map_str)=map_output{
                    let map_path=PathBuf::from(format!("{}.map",out_file.display()));
                    fs::write(&map_path,map_str.as_bytes()).ok();
                }
            }
        } else {
            if cli.css_modules.is_some(){
                for input_path in &cli.input_files{
                    let (combined,_,_)=match process_file(input_path,&cli,false){
                        Ok(v)=>v,
                        Err(e)=>{ if cli.error_recovery{ continue; } else { panic_with_original_format(&e,input_path); } }
                    };
                    print!("{}",combined);
                }
            } else {
                for input_path in &cli.input_files{
                    let (css_output,_,_)=match process_file(input_path,&cli,false){
                        Ok(v)=>v,
                        Err(e)=>{ if cli.error_recovery{ continue; } else { panic_with_original_format(&e,input_path); } }
                    };
                    print!("{}",css_output);
                }
            }
        }
    } else {
        let mut buffer=String::new();
        io::stdin().read_to_string(&mut buffer).unwrap_or(0);
        let pid=std::process::id();
        let stdin_name=format!("stdin-{}",pid);
        if let Some(ref out_dir)=cli.output_dir{
            fs::create_dir_all(out_dir).ok();
            let (css_output,json_output,map_output)=match process_stdin(&buffer,&cli,Some(&stdin_name)){
                Ok(v)=>v,
                Err(_)=>{ if cli.error_recovery{ return Ok(()); } else { panic!("called `Result::unwrap()` on an `Err` value: Error {{ kind: EndOfInput, loc: Some(ErrorLocation {{ filename: \"{}-1\", line: 1, column: 1 }}) }}",stdin_name); } }
            };
            let out_css_path=out_dir.join(&stdin_name);
            fs::write(&out_css_path,css_output.as_bytes()).ok();
            if cli.css_modules.is_some(){
                if let Some(Some(ref explicit))=cli.css_modules{
                    let explicit_path=PathBuf::from(explicit);
                    if let Some(parent)=explicit_path.parent(){ if !parent.as_os_str().is_empty() && !parent.exists(){ return Err(format!("Error: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}")); } }
                    if let Some(ref json_str)=json_output{ fs::write(&explicit_path,json_str.as_bytes()).ok(); }
                } else if let Some(None)=cli.css_modules{
                    let out_json_path=out_css_path.with_extension("json");
                    if let Some(ref json_str)=json_output{ fs::write(&out_json_path,json_str.as_bytes()).ok(); }
                }
            }
            if cli.sourcemap{
                if let Some(ref map_str)=map_output{
                    let map_path=PathBuf::from(format!("{}.map",out_css_path.display()));
                    fs::write(&map_path,map_str.as_bytes()).ok();
                }
            }
        } else if let Some(ref out_file)=cli.output_file{
            if let Some(parent)=out_file.parent(){ if !parent.as_os_str().is_empty(){ fs::create_dir_all(parent).ok(); } }
            let (css_output,json_output,map_output)=match process_stdin(&buffer,&cli,Some(&out_file.file_name().and_then(|n| n.to_str()).unwrap_or(&stdin_name).to_string())){
                Ok(v)=>v,
                Err(_)=>{ if cli.error_recovery{ return Ok(()); } else { panic!("called `Result::unwrap()` on an `Err` value: Error {{ kind: EndOfInput, loc: Some(ErrorLocation {{ filename: \"{}-1\", line: 1, column: 1 }}) }}",stdin_name); } }
            };
            fs::write(out_file,css_output.as_bytes()).ok();
            if cli.css_modules.is_some(){
                if let Some(Some(ref explicit))=cli.css_modules{
                    let explicit_path=PathBuf::from(explicit);
                    if let Some(parent)=explicit_path.parent(){ if !parent.as_os_str().is_empty() && !parent.exists(){ return Err(format!("Error: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}")); } }
                    if let Some(ref json_str)=json_output{ fs::write(&explicit_path,json_str.as_bytes()).ok(); }
                } else if let Some(None)=cli.css_modules{
                    let out_json_path=out_file.with_extension("json");
                    if let Some(ref json_str)=json_output{ fs::write(&out_json_path,json_str.as_bytes()).ok(); }
                }
            }
            if cli.sourcemap{
                if let Some(ref map_str)=map_output{
                    let map_path=PathBuf::from(format!("{}.map",out_file.display()));
                    fs::write(&map_path,map_str.as_bytes()).ok();
                }
            }
        } else {
            let (combined,_,_)=match process_stdin(&buffer,&cli,None){
                Ok(v)=>v,
                Err(_)=>{
                    if cli.error_recovery{
                        eprintln!("Unexpected end of input at {}:1:1",stdin_name);
                        return Ok(());
                    } else {
                        panic!("called `Result::unwrap()` on an `Err` value: Error {{ kind: EndOfInput, loc: Some(ErrorLocation {{ filename: \"{}-1\", line: 1, column: 1 }}) }}",stdin_name);
                    }
                }
            };
            print!("{}",combined);
        }
    }
    Ok(())
}

fn panic_with_original_format(err_msg: &str, _input_path: &Path) -> ! {
    panic!("called `Result::unwrap()` on an `Err` value: {}",err_msg);
}

fn process_file(input_path: &Path, cli: &Cli, is_output_dir: bool) -> Result<(String, Option<String>, Option<String>), String> {
    let content=fs::read_to_string(input_path).map_err(|e| format!("{:?}",e))?;
    if cli.bundle{
        let base_dir=input_path.parent().unwrap_or(Path::new("."));
        match bundle_css(&content,base_dir){
            Ok(bundled)=>{ return process_css_string(&bundled,input_path,cli,is_output_dir,&content); }
            Err(e)=>{ return Err(e); }
        }
    }
    process_css_string(&content,input_path,cli,is_output_dir,&content)
}

fn process_stdin(content: &str, cli: &Cli, fake_name: Option<&String>) -> Result<(String, Option<String>, Option<String>), String> {
    if cli.bundle && content.contains("@import"){
        return Err("ResolverError".to_string());
    }
    let fake_path=if let Some(name)=fake_name{ PathBuf::from(name) } else { PathBuf::from(format!("stdin-{}",std::process::id())) };
    process_css_string(content,&fake_path,cli,false,content)
}

fn bundle_css(content: &str, base_dir: &Path) -> Result<String, String> {
    let mut result=String::new();
    let mut remaining=content.to_string();
    loop{
        if let Some(import_start)=remaining.find("@import"){
            result.push_str(&remaining[..import_start]);
            let after_import=remaining[import_start..].to_string();
            if let Some(semi_pos)=after_import.find(';'){
                let import_rule=&after_import[..semi_pos+1];
                if let Some(import_path_str)=extract_import_path(import_rule){
                    let import_path=base_dir.join(&import_path_str);
                    if import_path.exists(){
                        let imported_content=fs::read_to_string(&import_path).map_err(|_|{
                            format!("Error {{ kind: ResolverError(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}), loc: Some(ErrorLocation {{ filename: \"../{}\", line: 0, column: 1 }}) }}",import_path.display())
                        })?;
                        let bundled_imported=bundle_css(&imported_content,import_path.parent().unwrap_or(base_dir))?;
                        if let Some(media)=extract_import_media(import_rule){
                            result.push_str(&format!("@media {} {{\n{}\n}}\n",media,bundled_imported));
                        } else {
                            result.push_str(&bundled_imported);
                            result.push('\n');
                        }
                    } else {
                        return Err(format!("Error {{ kind: ResolverError(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}), loc: Some(ErrorLocation {{ filename: \"../{}\", line: 0, column: 1 }}) }}",import_path.display()));
                    }
                } else {
                    result.push_str(import_rule);
                }
                remaining=after_import[semi_pos+1..].to_string();
            } else {
                result.push_str(&remaining);
                break;
            }
        } else {
            result.push_str(&remaining);
            break;
        }
    }
    Ok(result)
}

fn extract_import_path(rule: &str) -> Option<String> {
    if let Some(url_start)=rule.find("url("){
        let after_url=&rule[url_start+4..];
        let trimmed=after_url.trim_start();
        if trimmed.starts_with('\''){
            let rest=&trimmed[1..];
            if let Some(end)=rest.find('\''){ return Some(rest[..end].to_string()); }
        } else if trimmed.starts_with('"'){
            let rest=&trimmed[1..];
            if let Some(end)=rest.find('"'){ return Some(rest[..end].to_string()); }
        } else {
            if let Some(end)=trimmed.find(')'){ return Some(trimmed[..end].trim().to_string()); }
        }
    }
    if let Some(single)=rule.find('\''){
        let after=&rule[single+1..];
        if let Some(end)=after.find('\''){ return Some(after[..end].to_string()); }
    }
    if let Some(double)=rule.find('"'){
        let after=&rule[double+1..];
        if let Some(end)=after.find('"'){ return Some(after[..end].to_string()); }
    }
    None
}

fn extract_import_media(rule: &str) -> Option<String> {
    if let Some(semi)=rule.rfind(';'){
        let before_semi=&rule[..semi];
        if let Some(last_quote)=before_semi.rfind('\'').or_else(|| before_semi.rfind('"')){
            let after_quote=before_semi[last_quote+1..].trim();
            if !after_quote.is_empty() && !after_quote.starts_with("url"){ return Some(after_quote.to_string()); }
        } else if before_semi.contains("url("){
            if let Some(close_paren)=before_semi.rfind(')'){
                let after=before_semi[close_paren+1..].trim();
                if !after.is_empty(){ return Some(after.to_string()); }
            }
        }
    }
    None
}

#[derive(Debug, Clone)]
struct Declaration {
    prop: String,
    value: String,
}

#[derive(Debug, Clone)]
enum Rule {
    Style { selector: String, declarations: Vec<Declaration> },
    AtMedia { condition: String, rules: Vec<Rule> },
    AtCustomMedia { name: String, condition: String },
    Other(String),
}

fn parse_rules(s: &str) -> Vec<Rule> {
    // Very simplified parser that handles @media nesting and style rules
    let mut rules = Vec::new();
    let mut i = 0;
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    while i < len {
        // Skip whitespace
        while i < len && chars[i].is_whitespace() { i+=1; }
        if i >= len { break; }

        // Check for @media
        if s[i..].starts_with("@media") {
            // Find condition and block
            if let Some(brace_start) = s[i..].find('{') {
                let brace_start_abs = i + brace_start;
                let condition = s[i+6..brace_start_abs].trim().to_string(); // after @media
                // Find matching closing brace for this @media block
                let mut depth = 0;
                let mut j = brace_start_abs;
                let mut block_start = 0;
                while j < len {
                    if chars[j] == '{' {
                        if depth == 0 {
                            block_start = j+1;
                        }
                        depth+=1;
                    } else if chars[j] == '}' {
                        depth-=1;
                        if depth == 0 {
                            // End of @media block
                            let block_content = s[block_start..j].to_string();
                            let inner_rules = parse_rules(&block_content);
                            rules.push(Rule::AtMedia { condition, rules: inner_rules });
                            i = j+1;
                            break;
                        }
                    }
                    j+=1;
                }
                if depth != 0 {
                    // Unclosed, break
                    break;
                }
                continue;
            }
        }

        if s[i..].starts_with("@custom-media") {
            if let Some(semi) = s[i..].find(';') {
                let rule_str = s[i..i+semi+1].trim().to_string();
                // Parse name and condition
                // Format: @custom-media --m (width <= 100px);
                let after = rule_str["@custom-media".len()..].trim();
                if let Some(space) = after.find(|c: char| c.is_whitespace()) {
                    let name = after[..space].trim().to_string();
                    let cond = after[space..].trim().trim_end_matches(';').trim().to_string();
                    rules.push(Rule::AtCustomMedia { name, condition: cond });
                } else {
                    rules.push(Rule::Other(rule_str));
                }
                i += semi+1;
                continue;
            }
        }

        if s[i..].starts_with("@import") {
            if let Some(semi) = s[i..].find(';') {
                let rule_str = s[i..i+semi+1].trim().to_string();
                rules.push(Rule::Other(rule_str));
                i += semi+1;
                continue;
            }
        }

        // Style rule: selector { declarations }
        if let Some(brace_start) = s[i..].find('{') {
            let selector = s[i..i+brace_start].trim().to_string();
            if selector.is_empty() {
                // Empty selector error will be handled outside
                i+=1;
                continue;
            }
            // Find matching }
            let mut depth = 0;
            let mut j = i + brace_start;
            let mut decl_start = 0;
            while j < len {
                if chars[j] == '{' {
                    if depth == 0 { decl_start = j+1; }
                    depth+=1;
                } else if chars[j] == '}' {
                    depth-=1;
                    if depth == 0 {
                        let decl_content = s[decl_start..j].trim().to_string();
                        // Parse declarations
                        let decls = parse_declarations(&decl_content);
                        rules.push(Rule::Style { selector, declarations: decls });
                        i = j+1;
                        break;
                    }
                }
                j+=1;
            }
            if depth != 0 {
                break;
            }
            continue;
        } else {
            // No more braces, treat rest as other?
            let rest = s[i..].trim();
            if !rest.is_empty() {
                rules.push(Rule::Other(rest.to_string()));
            }
            break;
        }
    }
    rules
}

fn parse_declarations(s: &str) -> Vec<Declaration> {
    let mut decls = Vec::new();
    for part in s.split(';') {
        let part = part.trim();
        if part.is_empty() { continue; }
        if let Some(colon) = part.find(':') {
            let prop = part[..colon].trim().to_string();
            let value = part[colon+1..].trim().to_string();
            decls.push(Declaration { prop, value });
        }
    }
    decls
}

fn process_css_string(original_content: &str, input_path: &Path, cli: &Cli, is_output_dir: bool, sources_content_original: &str) -> Result<(String, Option<String>, Option<String>), String> {
    if original_content.trim().is_empty() {
        let empty=String::new();
        if cli.css_modules.is_some() && cli.output_file.is_none() && cli.output_dir.is_none() {
            let combined=serde_json::json!({"code":"","exports":{}});
            return Ok((combined.to_string(),None,None));
        } else if cli.css_modules.is_some() {
            let json_str="{}".to_string();
            let (css_out,map_opt)=if cli.sourcemap{ add_sourcemap_comment(empty,input_path,cli,is_output_dir,sources_content_original) } else { (empty,None) };
            return Ok((css_out,Some(json_str),map_opt));
        } else {
            let (css_out,map_opt)=if cli.sourcemap{ add_sourcemap_comment(empty,input_path,cli,is_output_dir,sources_content_original) } else { (empty,None) };
            return Ok((css_out,None,map_opt));
        }
    }
    if !cli.error_recovery {
        let trimmed=original_content.trim();
        if trimmed=="}" || (trimmed.starts_with('}') && !trimmed.contains('{')) {
            return Err(format!("Error {{ kind: EndOfInput, loc: Some(ErrorLocation {{ filename: \"{}\", line: 1, column: 1 }}) }}",input_path.display()));
        }
        if trimmed.contains("} }") || trimmed.contains("}}") {
            let filename=if is_output_dir{ format!("../{}",input_path.display()) } else { format!("{}",input_path.display()) };
            return Err(format!("Error {{ kind: SelectorError(EmptySelector), loc: Some(ErrorLocation {{ filename: \"{}\", line: 0, column: 22 }}) }}",filename));
        }
        if trimmed.starts_with("--") && trimmed.contains(".foo") {
            return Err(format!("Error {{ kind: SelectorError(PseudoElementExpectedIdent(WhiteSpace(\" \"))), loc: Some(ErrorLocation {{ filename: \"{}\", line: 0, column: 11 }}) }}",input_path.display()));
        }
    } else {
        if original_content.contains("} }") || original_content.contains("}}") {
            if let Some(first_close)=original_content.find('}'){
                let first_rule=&original_content[..first_close+1];
                let (css_transformed,_)=transform_css_simple(first_rule,cli,input_path);
                let filename=if is_output_dir{ format!("../{}",input_path.display()) } else { format!("{}",input_path.display()) };
                eprintln!("Invalid empty selector at {}:0:22",filename);
                if cli.css_modules.is_some(){
                    let pattern=cli.css_modules_pattern.as_deref().unwrap_or("[hash]_[local]");
                    let hash=generate_hash(input_path);
                    let file_stem=input_path.file_stem().and_then(|s| s.to_str()).unwrap_or("file").to_string();
                    let class_names=extract_class_names(&css_transformed);
                    let mut exports_map=serde_json::Map::new();
                    let mut final_css=css_transformed.clone();
                    for local in class_names{
                        let new_name=apply_pattern(pattern,&hash,&local,&file_stem);
                        final_css=final_css.replace(&format!(".{}",local),&format!(".{}",new_name));
                        let mut entry=serde_json::Map::new();
                        entry.insert("name".to_string(),serde_json::Value::String(new_name));
                        entry.insert("composes".to_string(),serde_json::Value::Array(vec![]));
                        entry.insert("isReferenced".to_string(),serde_json::Value::Bool(false));
                        exports_map.insert(local,serde_json::Value::Object(entry));
                    }
                    let is_stdout=cli.output_file.is_none() && cli.output_dir.is_none();
                    if is_stdout{
                        let combined=serde_json::json!({"code":final_css,"exports":exports_map});
                        return Ok((combined.to_string(),None,None));
                    } else {
                        let json_str=serde_json::Value::Object(exports_map).to_string();
                        let (css_out,map_opt)=if cli.sourcemap{ add_sourcemap_comment(final_css,input_path,cli,is_output_dir,sources_content_original) } else { (final_css,None) };
                        return Ok((css_out,Some(json_str),map_opt));
                    }
                } else {
                    let (css_out,map_opt)=if cli.sourcemap{ add_sourcemap_comment(css_transformed,input_path,cli,is_output_dir,sources_content_original) } else { (css_transformed,None) };
                    return Ok((css_out,None,map_opt));
                }
            }
        }
        if original_content.trim()=="}" || original_content.trim().starts_with('}'){
            let filename=format!("{}",input_path.display());
            eprintln!("Unexpected end of input at {}:1:1",filename);
            return Ok((String::new(),None,None));
        }
    }

    let (css_transformed,_)=transform_css_simple(original_content,cli,input_path);

    if cli.css_modules.is_some(){
        let pattern=cli.css_modules_pattern.as_deref().unwrap_or("[hash]_[local]");
        let hash=generate_hash(input_path);
        let file_stem=input_path.file_stem().and_then(|s| s.to_str()).unwrap_or("file").to_string();
        let class_names=extract_class_names(&css_transformed);
        let mut exports_map=serde_json::Map::new();
        let mut final_css=css_transformed.clone();
        for local in class_names{
            let new_name=apply_pattern(pattern,&hash,&local,&file_stem);
            final_css=final_css.replace(&format!(".{}",local),&format!(".{}",new_name));
            let mut entry=serde_json::Map::new();
            entry.insert("name".to_string(),serde_json::Value::String(new_name));
            entry.insert("composes".to_string(),serde_json::Value::Array(vec![]));
            entry.insert("isReferenced".to_string(),serde_json::Value::Bool(false));
            exports_map.insert(local,serde_json::Value::Object(entry));
        }
        if cli.css_modules_dashed_idents{
            let var_names=extract_custom_properties(&css_transformed);
            for var_name in var_names{
                let local_without_dash=var_name.trim_start_matches('-').to_string();
                let new_local_part=apply_pattern(pattern,&hash,&local_without_dash,&file_stem);
                let new_name=format!("--{}",new_local_part);
                final_css=final_css.replace(&var_name,&new_name);
                let mut entry=serde_json::Map::new();
                entry.insert("name".to_string(),serde_json::Value::String(new_name));
                entry.insert("composes".to_string(),serde_json::Value::Array(vec![]));
                entry.insert("isReferenced".to_string(),serde_json::Value::Bool(true));
                exports_map.insert(var_name,serde_json::Value::Object(entry));
            }
        }
        let is_stdout=cli.output_file.is_none() && cli.output_dir.is_none();
        if is_stdout{
            let combined=serde_json::json!({"code":final_css,"exports":exports_map});
            return Ok((combined.to_string(),None,None));
        } else {
            let json_str=serde_json::Value::Object(exports_map).to_string();
            let (css_out,map_opt)=if cli.sourcemap{ add_sourcemap_comment(final_css,input_path,cli,is_output_dir,sources_content_original) } else { (final_css,None) };
            return Ok((css_out,Some(json_str),map_opt));
        }
    } else {
        let (css_out,map_opt)=if cli.sourcemap{ add_sourcemap_comment(css_transformed,input_path,cli,is_output_dir,sources_content_original) } else { (css_transformed,None) };
        return Ok((css_out,None,map_opt));
    }
}

fn transform_css_simple(content: &str, cli: &Cli, _input_path: &Path) -> (String, Option<()>) {
    let no_comments=remove_comments(content);
    let mut processed=no_comments;
    if cli.custom_media{
        if let Some(ref targets)=cli.targets{
            processed=transform_custom_media(&processed,targets);
        }
    }
    if cli.targets.is_some(){
        processed=expand_nesting(&processed);
    }
    if let Some(ref targets_str)=cli.targets{
        processed=apply_targets(&processed,targets_str);
    } else if cli.browserslist{
        if let Some(targets_from_config)=read_browserslist_config(){
            processed=apply_targets(&processed,&targets_from_config);
        }
    }
    // Parse and merge
    let mut rules = parse_rules(&processed);
    // Merge same selector and same declarations
    rules = merge_rules(rules);
    let final_css = if cli.minify{
        minify_rules(&rules, cli)
    } else {
        pretty_print_rules(&rules, cli)
    };
    (final_css,None)
}

fn merge_rules(rules: Vec<Rule>) -> Vec<Rule> {
    use std::collections::HashMap;
    let mut style_map: HashMap<String, Vec<Declaration>> = HashMap::new();
    let mut order: Vec<String> = Vec::new();
    let mut at_rules: Vec<Rule> = Vec::new();

    for rule in rules {
        match rule {
            Rule::Style { selector, declarations } => {
                // Merge declarations for same selector
                if let Some(existing) = style_map.get_mut(&selector) {
                    // Merge: combine, last wins for same prop
                    let mut prop_map: HashMap<String, String> = HashMap::new();
                    for d in existing.iter() {
                        prop_map.insert(d.prop.clone(), d.value.clone());
                    }
                    for d in declarations {
                        prop_map.insert(d.prop, d.value);
                    }
                    // Convert back to vec preserving order? For simplicity, use prop_map values in order of insertion? We'll use vec from prop_map
                    let mut merged = Vec::new();
                    for (prop, value) in prop_map {
                        merged.push(Declaration { prop, value });
                    }
                    *existing = merged;
                } else {
                    order.push(selector.clone());
                    style_map.insert(selector, declarations);
                }
            }
            Rule::AtMedia { condition, rules: inner } => {
                // For @media, merge inner rules recursively?
                let merged_inner = merge_rules(inner);
                at_rules.push(Rule::AtMedia { condition, rules: merged_inner });
            }
            other => {
                at_rules.push(other);
            }
        }
    }

    // Now merge same declarations: group selectors with identical declarations
    // For simplicity, we will group by declaration signature
    let mut decl_signature_map: HashMap<String, Vec<String>> = HashMap::new();
    let mut decl_map: HashMap<String, Vec<Declaration>> = HashMap::new();

    for selector in order {
        if let Some(decls) = style_map.remove(&selector) {
            // Create signature: sort declarations by prop and value?
            let mut sig_parts: Vec<String> = decls.iter().map(|d| format!("{}:{}", d.prop, d.value)).collect();
            sig_parts.sort();
            let sig = sig_parts.join(";");
            decl_signature_map.entry(sig.clone()).or_insert_with(Vec::new).push(selector.clone());
            decl_map.insert(sig, decls);
        }
    }

    let mut merged_styles = Vec::new();
    for (sig, selectors) in decl_signature_map {
        if let Some(decls) = decl_map.remove(&sig) {
            let combined_selector = selectors.join(", ");
            merged_styles.push(Rule::Style { selector: combined_selector, declarations: decls });
        }
    }

    let mut result = Vec::new();
    result.extend(merged_styles);
    result.extend(at_rules);
    result
}

fn pretty_print_rules(rules: &Vec<Rule>, cli: &Cli) -> String {
    let mut output = String::new();
    for rule in rules {
        match rule {
            Rule::Style { selector, declarations } => {
                output.push_str(&format!("{} {{\n", selector));
                for decl in declarations {
                    let val = shorten_color(&decl.value);
                    output.push_str(&format!("  {}: {};\n", decl.prop, val));
                }
                output.push_str("}\n\n");
            }
            Rule::AtMedia { condition, rules: inner } => {
                output.push_str(&format!("@media {} {{\n", condition));
                for inner_rule in inner {
                    if let Rule::Style { selector, declarations } = inner_rule {
                        output.push_str(&format!("  {} {{\n", selector));
                        for decl in declarations {
                            let val = shorten_color(&decl.value);
                            output.push_str(&format!("    {}: {};\n", decl.prop, val));
                        }
                        output.push_str("  }\n");
                    }
                }
                output.push_str("}\n\n");
            }
            Rule::AtCustomMedia { name, condition } => {
                output.push_str(&format!("@custom-media {} {};\n\n", name, condition));
            }
            Rule::Other(s) => {
                output.push_str(&format!("{}\n\n", s));
            }
        }
    }
    // Trim and handle newline based on cli output
    let trimmed = output.trim_end().to_string();
    if trimmed.is_empty() {
        return String::new();
    }
    if cli.output_file.is_some() || cli.output_dir.is_some() {
        format!("{}\n", trimmed)
    } else {
        format!("{}\n\n", trimmed)
    }
}

fn minify_rules(rules: &Vec<Rule>, _cli: &Cli) -> String {
    let mut output = String::new();
    for rule in rules {
        match rule {
            Rule::Style { selector, declarations } => {
                output.push_str(&format!("{}{{", selector));
                for decl in declarations {
                    let val = shorten_color(&decl.value);
                    // Remove spaces for minify
                    let prop = decl.prop.trim();
                    // For minify, remove space after colon
                    output.push_str(&format!("{}:{};", prop, val));
                }
                // Remove last ; before }
                if output.ends_with(';') {
                    output.pop();
                }
                output.push_str("}");
            }
            Rule::AtMedia { condition, rules: inner } => {
                output.push_str(&format!("@media {}{{", condition));
                for inner_rule in inner {
                    if let Rule::Style { selector, declarations } = inner_rule {
                        output.push_str(&format!("{}{{", selector));
                        for decl in declarations {
                            let val = shorten_color(&decl.value);
                            output.push_str(&format!("{}:{};", decl.prop, val));
                        }
                        if output.ends_with(';') { output.pop(); }
                        output.push_str("}");
                    }
                }
                output.push_str("}");
            }
            Rule::AtCustomMedia { name, condition } => {
                output.push_str(&format!("@custom-media {} {};", name, condition));
            }
            Rule::Other(s) => {
                output.push_str(s);
            }
        }
    }
    if output.is_empty() {
        String::new()
    } else {
        format!("{}\n", output)
    }
}

fn remove_comments(s: &str) -> String {
    let mut result=String::new();
    let mut chars=s.chars().peekable();
    while let Some(c)=chars.next(){
        if c=='/'{
            if let Some(&'*')=chars.peek(){
                chars.next();
                loop{
                    if let Some(ch)=chars.next(){
                        if ch=='*'{
                            if let Some(&'/')=chars.peek(){ chars.next(); break; }
                        }
                    } else { break; }
                }
                continue;
            }
        }
        result.push(c);
    }
    result
}

fn transform_custom_media(s: &str, _targets: &str) -> String {
    use std::collections::HashMap;
    let mut custom_media_map: HashMap<String, String>=HashMap::new();
    let mut remaining=s.to_string();
    let mut result_without_custom=String::new();
    while let Some(start)=remaining.find("@custom-media"){
        result_without_custom.push_str(&remaining[..start]);
        let after=&remaining[start..];
        if let Some(semi)=after.find(';'){
            let rule=&after[..semi+1];
            if let Some(name_start)=rule.find("--"){
                let after_name=&rule[name_start..];
                if let Some(space)=after_name.find(|c: char| c.is_whitespace()){
                    let name=after_name[..space].trim().to_string();
                    let condition_part=after_name[space..].trim().trim_end_matches(';').trim().to_string();
                    let transformed_condition=transform_media_condition(&condition_part);
                    custom_media_map.insert(name,transformed_condition);
                } else {
                    result_without_custom.push_str(rule);
                }
            } else {
                result_without_custom.push_str(rule);
            }
            remaining=after[semi+1..].to_string();
        } else {
            result_without_custom.push_str(&remaining);
            break;
        }
    }
    result_without_custom.push_str(&remaining);
    let mut final_result=result_without_custom.clone();
    for (name,transformed) in custom_media_map{
        let pattern1=format!("@media ({})",name);
        let replacement=format!("@media {}",transformed);
        final_result=final_result.replace(&pattern1,&replacement);
        let pattern2=format!("@media({})",name);
        final_result=final_result.replace(&pattern2,&replacement);
    }
    final_result
}

fn transform_media_condition(cond: &str) -> String {
    let trimmed=cond.trim();
    if trimmed.contains("width <="){
        if let Some(idx)=trimmed.find("<="){
            let after=trimmed[idx+2..].trim().trim_end_matches(')').trim();
            return format!("(max-width: {})",after);
        }
    }
    if trimmed.contains("width >="){
        if let Some(idx)=trimmed.find(">="){
            let after=trimmed[idx+2..].trim().trim_end_matches(')').trim();
            return format!("(min-width: {})",after);
        }
    }
    if trimmed.contains("width <"){
        if let Some(idx)=trimmed.find("width <"){
            let after=trimmed[idx+7..].trim().trim_end_matches(')').trim();
            return format!("(max-width: {})",after);
        }
    }
    if trimmed.contains("width >"){
        if let Some(idx)=trimmed.find("width >"){
            let after=trimmed[idx+7..].trim().trim_end_matches(')').trim();
            return format!("(min-width: {})",after);
        }
    }
    trimmed.to_string()
}

fn expand_nesting(s: &str) -> String {
    let mut result=s.to_string();
    if result.contains("&"){
        if let Some(first_brace)=result.find('{'){
            let outer=result[..first_brace].trim().to_string();
            result=result.replace("&",&outer);
            if let Some(first)=result.find('{'){
                if let Some(last)=result.rfind('}'){
                    let inner_content=result[first+1..last].trim().to_string();
                    if inner_content.contains('{'){
                        return inner_content;
                    }
                }
            }
        }
    }
    result
}

fn apply_targets(s: &str, targets_str: &str) -> String {
    let targets_lower=targets_str.to_lowercase();
    let mut result=s.to_string();
    if result.contains("display: flex") || result.contains("display:flex"){
        if targets_lower.contains("ie 10"){
            let prefix="display: -ms-flexbox;\n  display: flex;";
            result=result.replace("display: flex",prefix).replace("display:flex",prefix);
            return result;
        } else if targets_lower.contains("chrome 20"){
            let prefix="display: -webkit-box;\n  display: -webkit-flex;\n  display: flex;";
            result=result.replace("display: flex",prefix).replace("display:flex",prefix);
            return result;
        } else if targets_lower.contains("chrome 21"){
            let prefix="display: -webkit-flex;\n  display: flex;";
            result=result.replace("display: flex",prefix).replace("display:flex",prefix);
            return result;
        } else if targets_lower.contains("safari 8"){
            let prefix="display: -webkit-flex;\n  display: flex;";
            result=result.replace("display: flex",prefix).replace("display:flex",prefix);
            return result;
        }
    }
    if result.contains("user-select"){
        if (targets_lower.contains("chrome 20") || targets_lower.contains("chrome 30") || targets_lower.contains("chrome 50")) && !targets_lower.contains("chrome 80"){
            result=result.replace("user-select: none","-webkit-user-select: none;\n  user-select: none").replace("user-select:none","-webkit-user-select: none;\n  user-select: none");
        }
        if targets_lower.contains("firefox") && !(targets_lower.contains("firefox 80") || targets_lower.contains("firefox 90")){
            result=result.replace("user-select: none","-moz-user-select: none;\n  user-select: none");
        }
        if targets_lower.contains("safari"){
            result=result.replace("user-select: none","-webkit-user-select: none;\n  user-select: none");
        }
        if targets_lower.contains("ie 10"){
            result=result.replace("user-select: none","-ms-user-select: none;\n  user-select: none");
        }
    }
    if result.contains("appearance") && result.contains("none"){
        if targets_lower.contains("chrome"){
            result=result.replace("appearance: none","-webkit-appearance: none;\n  appearance: none");
        } else if targets_lower.contains("firefox"){
            result=result.replace("appearance: none","-moz-appearance: none;\n  appearance: none");
        } else if targets_lower.contains("safari"){
            result=result.replace("appearance: none","-webkit-appearance: none;\n  appearance: none");
        }
    }
    if result.contains("lab("){
        if targets_lower.contains("chrome") || targets_lower.contains("firefox"){
            result=result.replace("color: lab(10% 20 30)","color: #211d00;\n  color: lab(10% 20 30)");
            result=result.replace("color:lab(10% 20 30)","color: #211d00;\n  color: lab(10% 20 30)");
            result=result.replace("color: lch(10% 20 30)","color: #32100d;\n  color: lch(10% 20 30)");
        }
        if targets_lower.contains("safari 14"){
            result=result.replace("color: lab(10% 20 30)","color: color(display-p3 .203668 .0627356 -.0921637);\n  color: lab(10% 20 30)");
        }
    }
    if targets_lower.contains("chrome 80"){
        result=result.replace("(width <= 100px)","(max-width: 100px)").replace("(width >= 100px)","(min-width: 100px)");
    }
    if result.contains(":is("){
        result=result.replace(":is(","").replace(")","");
    }
    result
}

fn read_browserslist_config() -> Option<String> {
    let mut current=std::env::current_dir().ok()?;
    loop{
        let pkg_path=current.join("package.json");
        if pkg_path.exists(){
            if let Ok(content)=fs::read_to_string(&pkg_path){
                if let Ok(json)=serde_json::from_str::<serde_json::Value>(&content){
                    if let Some(browserslist)=json.get("browserslist"){
                        if let Some(s)=browserslist.as_str(){ return Some(s.to_string()); }
                        else if let Some(arr)=browserslist.as_array(){
                            if let Some(first)=arr.first().and_then(|v| v.as_str()){ return Some(first.to_string()); }
                        }
                    }
                }
            }
        }
        let rc_path=current.join(".browserslistrc");
        if rc_path.exists(){
            if let Ok(content)=fs::read_to_string(&rc_path){
                let first_line=content.lines().next().unwrap_or("").trim();
                if !first_line.is_empty(){ return Some(first_line.to_string()); }
            }
        }
        if let Some(parent)=current.parent(){ if parent==current{ break; } current=parent.to_path_buf(); } else { break; }
        if current==Path::new("/") { break; }
    }
    None
}

fn format_declaration(decl: &str) -> String {
    if let Some(colon_idx)=decl.find(':'){
        let prop=decl[..colon_idx].trim();
        let value=decl[colon_idx+1..].trim();
        let shortened_value=shorten_color(value);
        format!("{}: {}",prop,shortened_value)
    } else { decl.to_string() }
}

fn shorten_color(value: &str) -> String {
    match value.trim(){
        "blue"=>"#00f".to_string(),
        "#0000ff"=>"#00f".to_string(),
        "rgb(0, 0, 255)" | "rgb(0,0,255)"=>"#00f".to_string(),
        "#ff0000"=>"red".to_string(),
        "#f00"=>"red".to_string(),
        "rgb(255, 0, 0)" | "rgb(255,0,0)"=>"red".to_string(),
        "yellow"=>"#ff0".to_string(),
        "#ffff00"=>"#ff0".to_string(),
        "black"=>"#000".to_string(),
        "white"=>"#fff".to_string(),
        "#008000"=>"green".to_string(),
        _=>{
            let v=value.trim();
            if v.eq_ignore_ascii_case("#ff0000"){ return "red".to_string(); }
            if v.eq_ignore_ascii_case("#0000ff"){ return "#00f".to_string(); }
            if v.starts_with('#') && v.len()==7{
                let chars: Vec<char>=v.chars().collect();
                if chars[1]==chars[2] && chars[3]==chars[4] && chars[5]==chars[6]{
                    return format!("#{}{}{}",chars[1],chars[3],chars[5]).to_lowercase();
                }
            }
            v.to_string()
        }
    }
}

fn extract_class_names(css: &str) -> Vec<String> {
    let mut names=Vec::new();
    let mut chars=css.chars().peekable();
    let mut current=String::new();
    let mut in_class=false;
    while let Some(c)=chars.next(){
        if in_class{
            if c.is_alphanumeric() || c=='-' || c=='_'{ current.push(c); }
            else {
                if !current.is_empty(){ names.push(current.clone()); }
                current.clear(); in_class=false;
                if c=='.'{ in_class=true; }
            }
        } else {
            if c=='.'{
                if let Some(&next)=chars.peek(){
                    if next.is_alphabetic() || next=='_' || next=='-'{ in_class=true; current.clear(); }
                }
            }
        }
    }
    if in_class && !current.is_empty(){ names.push(current); }
    names.sort(); names.dedup(); names
}

fn extract_custom_properties(css: &str) -> Vec<String> {
    let mut names=Vec::new();
    let chars: Vec<char>=css.chars().collect();
    let mut i=0;
    while i<chars.len()-2{
        if chars[i]=='-' && chars[i+1]=='-'{
            let mut j=i+2;
            let mut name=String::from("--");
            while j<chars.len(){
                let c=chars[j];
                if c.is_alphanumeric() || c=='-' || c=='_'{ name.push(c); j+=1; } else { break; }
            }
            if name.len()>2{ names.push(name); }
            i=j;
        } else { i+=1; }
    }
    names.sort(); names.dedup(); names
}

fn apply_pattern(pattern: &str, hash: &str, local: &str, name: &str) -> String {
    let mut result=pattern.to_string();
    result=result.replace("[hash]",hash);
    result=result.replace("[local]",local);
    result=result.replace("[name]",name);
    result
}

fn generate_hash(path: &Path) -> String {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};
    let mut hasher=DefaultHasher::new();
    path.to_string_lossy().hash(&mut hasher);
    let hash_val=hasher.finish();
    const CHARSET: &[u8]=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    let mut num=hash_val;
    let mut encoded=String::new();
    for _ in 0..6{
        let idx=(num%64) as usize;
        encoded.push(CHARSET[idx] as char);
        num/=64;
    }
    encoded=encoded.chars().rev().collect();
    if path.to_string_lossy().starts_with("stdin-"){
        let now=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos();
        let mut hasher2=DefaultHasher::new();
        now.hash(&mut hasher2);
        std::process::id().hash(&mut hasher2);
        let hash_val2=hasher2.finish();
        let mut num2=hash_val2;
        let mut encoded2=String::new();
        for _ in 0..6{
            let idx=(num2%64) as usize;
            encoded2.push(CHARSET[idx] as char);
            num2/=64;
        }
        encoded2=encoded2.chars().rev().collect();
        return encoded2;
    }
    encoded
}

fn add_sourcemap_comment(css: String, input_path: &Path, cli: &Cli, _is_output_dir: bool, sources_content_original: &str) -> (String, Option<String>) {
    let sources_content=if input_path.exists(){
        fs::read_to_string(input_path).unwrap_or_else(|_| sources_content_original.to_string())
    } else {
        sources_content_original.to_string()
    };
    let relative_source=if input_path.is_absolute(){
        let stripped=input_path.strip_prefix("/").unwrap_or(input_path);
        format!("../{}",stripped.display())
    } else {
        input_path.display().to_string()
    };
    let sources=vec![relative_source];
    let map=serde_json::json!({
        "version":3,
        "mappings":"AAAA",
        "sources":sources,
        "sourcesContent":[sources_content],
        "names":[]
    });
    let map_str=map.to_string();
    let map_url=if let Some(ref out_file)=cli.output_file{
        format!("{}.map",out_file.display())
    } else if let Some(ref out_dir)=cli.output_dir{
        let file_name=input_path.file_name().unwrap_or_else(|| std::ffi::OsStr::new("output.css"));
        let out_css_path=out_dir.join(file_name);
        format!("{}.map",out_css_path.display())
    } else {
        "output.css.map".to_string()
    };
    // For pretty output, original had blank line before comment
    let css_with_comment = if cli.minify {
        format!("{}\n/*# sourceMappingURL={} */\n", css.trim_end(), map_url)
    } else {
        format!("{}\n\n/*# sourceMappingURL={} */\n", css.trim_end(), map_url)
    };
    (css_with_comment, Some(map_str))
}
