            "--error-recovery" => { cli.error_recovery=true; cli.flag_order.push("--error-recovery".to_string()); i+=1; }
            "-m" | "--minify" => { cli.minify=true; cli.flag_order.push("--minify".to_string()); i+=1; }
            "-o" | "--output-file" => {
