    // Very simplified validation: split by comma, each part should contain known browser and version
    let lower = targets_str.to_lowercase();
    // Known browsers
    let known = ["chrome", "firefox", "safari", "ie", "edge", "opera", "ios", "android", "electron", "samsung"];
    // If empty string, should not panic? Original for empty string gave output with no transformation and exit 0
    if lower.trim().is_empty() {
        return;
    }
    // Split by comma
    for part in lower.split(',') {
        let part = part.trim();
        if part.is_empty() { continue; }
        let mut found = false;
        for browser in &known {
            if part.starts_with(browser) {
                // After browser name, should have space and version
                let rest = part[browser.len()..].trim();
                if rest.is_empty() {
                    // No version -> panic
                    panic!("called `Result::unwrap()` on an `Err` value: Nom(\"\")");
