                }
            } else {
                let idx = merged_styles.len();
                seen_sigs.insert(sig, idx);
                merged_styles.push(Rule::Style { selector, declarations: decls });
            }
        }
    }
    let mut result = Vec::new();
    result.extend(merged_styles);
    result.extend(at_rules);
    result
}"""

